# Procedural Lab Components — Three.js

Complete, drop-in ES module. Requires **three ≥ r160** and the standard `RoundedBoxGeometry` addon.

```js
/* lab-components.js — procedural builders for 6 laboratory electrical components */
import * as THREE from 'three';
import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';

const D2R = THREE.MathUtils.degToRad;

/* ══════════════════════════════════════════════════════════════════
   SHARED HELPERS
   ══════════════════════════════════════════════════════════════════ */

const rubber = (color, rough = 0.62) =>
  new THREE.MeshStandardMaterial({ color, roughness: rough, metalness: 0.0 });

const metal = (color, rough = 0.25) =>
  new THREE.MeshStandardMaterial({ color, roughness: rough, metalness: 1.0 });

/** Lathe from [[radius, y], ...] pairs. */
function lathe(pairs, segments = 64) {
  return new THREE.LatheGeometry(pairs.map(([r, y]) => new THREE.Vector2(r, y)), segments);
}

/** Canvas → CanvasTexture helper. */
function canvasTexture(w, h, draw) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  draw(c.getContext('2d'), w, h);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 8;
  return t;
}

/** Text label baked into a texture (transparent background by default). */
function textTexture(text, {
  w = 512, h = 512, bg = null, color = '#ffffff',
  font = 'bold 300px "Arial Black", Arial, sans-serif', dy = 0,
} = {}) {
  return canvasTexture(w, h, (ctx) => {
    if (bg) { ctx.fillStyle = bg; ctx.fillRect(0, 0, w, h); }
    ctx.fillStyle = color;
    ctx.font = font;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(text, w / 2, h / 2 + dy);
  });
}

/** Decal wrapped onto a cylinder of `radius` (theta 0 == +Z). */
function curvedDecal(radius, height, thetaCenter, thetaLength, texture) {
  const geo = new THREE.CylinderGeometry(
    radius, radius, height, 32, 1, true,
    thetaCenter - thetaLength / 2, thetaLength,
  );
  const mat = new THREE.MeshStandardMaterial({
    map: texture, transparent: true, roughness: 0.55, metalness: 0.0,
    depthWrite: false, polygonOffset: true, polygonOffsetFactor: -2,
    polygonOffsetUnits: -2,
  });
  return new THREE.Mesh(geo, mat);
}

/** Flat text plane lying on a surface facing +Y. */
function topDecal(texture, w, h) {
  const m = new THREE.Mesh(
    new THREE.PlaneGeometry(w, h),
    new THREE.MeshStandardMaterial({ map: texture, transparent: true, roughness: 0.55, depthWrite: false }),
  );
  m.rotation.x = -Math.PI / 2;
  return m;
}


/* ══════════════════════════════════════════════════════════════════
   1) AA BATTERY 1.5V
   Body 4.8 tall (Y −2.4…+2.4), radius 0.72.
   Blue jacket 1.4 (Y +1.0…+2.4) · black jacket 3.4 (Y −2.4…+1.0)
   Silver cap w/ groove + nickel nub (≈0.44 above body), flat − plate.
   ══════════════════════════════════════════════════════════════════ */
export function createAABattery({ labels = true } = {}) {
  const g = new THREE.Group();
  g.name = 'AA_Battery_1.5V';

  const R = 0.72;
  const matBlue  = new THREE.MeshStandardMaterial({ color: 0x0284c7, roughness: 0.30, metalness: 0.05 });
  const matBlack = new THREE.MeshStandardMaterial({ color: 0x18181b, roughness: 0.80, metalness: 0.00 });
  const matNickel = metal(0xd9d9e0, 0.18);

  /* ── jackets ─────────────────────────────────────────────── */
  const lower = new THREE.Mesh(new THREE.CylinderGeometry(R, R, 3.4, 64, 1), matBlack);
  lower.position.y = -0.7;                       // −2.4 … +1.0
  const upper = new THREE.Mesh(new THREE.CylinderGeometry(R, R, 1.4, 64, 1), matBlue);
  upper.position.y = 1.7;                        // +1.0 … +2.4
  g.add(lower, upper);

  // seam ring at the colour break
  const seam = new THREE.Mesh(new THREE.TorusGeometry(R + 0.004, 0.012, 8, 64), matBlack);
  seam.rotation.x = Math.PI / 2;
  seam.position.y = 1.0;
  g.add(seam);

  /* ── bottom negative contact plate ───────────────────────── */
  const plate = new THREE.Mesh(new THREE.CylinderGeometry(R, R - 0.02, 0.04, 64), matNickel);
  plate.position.y = -2.42;
  g.add(plate);
  const plateRing = new THREE.Mesh(new THREE.TorusGeometry(0.56, 0.015, 8, 48), matNickel);
  plateRing.rotation.x = Math.PI / 2;
  plateRing.position.y = -2.445;
  g.add(plateRing);

  /* ── top cap: beveled ring + groove + raised nub ─────────── */
  // profile is local to the top of the body (y = 2.4)
  const capProfile = [
    [0.720, 0.000], [0.736, 0.030], [0.736, 0.095], [0.700, 0.155], // outer bevel
    [0.560, 0.180],                                                  // top face (outer)
    [0.522, 0.158], [0.486, 0.104], [0.446, 0.158],                  // circular groove
    [0.404, 0.180],                                                  // top face (inner)
    [0.240, 0.182],                                                  // down to nub base
    [0.220, 0.215], [0.204, 0.380], [0.150, 0.425], [0.000, 0.440],  // nickel nub (h≈0.25)
  ];
  const cap = new THREE.Mesh(lathe(capProfile, 64), matNickel);
  cap.position.y = 2.4;
  g.add(cap);

  /* ── decals ──────────────────────────────────────────────── */
  if (labels) {
    const plusTex = textTexture('+', { w: 256, h: 256, color: '#09090b', font: 'bold 240px Arial' });
    for (const th of [0, Math.PI]) {
      const d = curvedDecal(R + 0.003, 0.46, th, 0.55, plusTex);
      d.position.y = 1.78;
      g.add(d);
    }
    const aaTex = textTexture('AA 1.5V', {
      w: 1024, h: 256, color: '#f4f4f5', font: 'bold 130px Arial',
    });
    for (const th of [Math.PI * 0.5, -Math.PI * 0.5]) {
      const d = curvedDecal(R + 0.003, 0.42, th, 1.6, aaTex);
      d.position.y = -0.55;
      g.add(d);
    }
  }

  g.userData.overallHeight = 4.8 + 0.44;
  return g;
}


/* ══════════════════════════════════════════════════════════════════
   2) MINIATURE E10 SCREW-BASE LIGHT BULB
   Origin = bottom of the solder bead. Globe r 0.65.
   Returns group with userData.setLit(bool) / .light / .filamentMat
   ══════════════════════════════════════════════════════════════════ */
export function createE10Bulb({ lit = true } = {}) {
  const g = new THREE.Group();
  g.name = 'E10_LightBulb';

  const matNickel = metal(0xcbd5e1, 0.22);
  const matBlack  = rubber(0x18181b, 0.55);

  /* ── solder contact bead (bottom tip) ────────────────────── */
  const bead = new THREE.Mesh(new THREE.SphereGeometry(0.13, 24, 16), matNickel);
  bead.scale.set(1, 0.55, 1);
  bead.position.y = 0.055;
  g.add(bead);

  /* ── black insulator ring ────────────────────────────────── */
  const insulator = new THREE.Mesh(new THREE.CylinderGeometry(0.30, 0.30, 0.10, 32), matBlack);
  insulator.position.y = 0.15;
  g.add(insulator);

  /* ── threaded E10 shell (rippled lathe) ──────────────────── */
  const R_SCREW = 0.30, Y0 = 0.20, H_SCREW = 0.55, TURNS = 5;
  const prof = [];
  const N = TURNS * 24;
  for (let i = 0; i <= N; i++) {
    const t = i / N;
    prof.push([R_SCREW + 0.032 * Math.sin(t * Math.PI * 2 * TURNS), Y0 + t * H_SCREW]);
  }
  prof.push([R_SCREW + 0.012, Y0 + H_SCREW + 0.02]);   // top lip
  const screw = new THREE.Mesh(new THREE.LatheGeometry(
    prof.map(([r, y]) => new THREE.Vector2(r, y)), 48), matNickel);
  g.add(screw);

  /* ── glass globe (teardrop lathe) ────────────────────────── */
  const GLOBE_Y = 0.72;
  const globeProfile = [
    [0.220, 0.000], [0.420, 0.100], [0.560, 0.280], [0.645, 0.550],
    [0.650, 0.750], [0.600, 0.980], [0.440, 1.160], [0.220, 1.270], [0.000, 1.300],
  ];
  const glassMat = new THREE.MeshPhysicalMaterial({
    color: 0xffffff, metalness: 0.0, roughness: 0.05,
    transmission: 0.96, ior: 1.5, thickness: 0.35,
    clearcoat: 1.0, clearcoatRoughness: 0.03,
    transparent: true, opacity: 1.0, envMapIntensity: 1.4,
    side: THREE.FrontSide,
  });
  const globe = new THREE.Mesh(lathe(globeProfile, 48), glassMat);
  globe.position.y = GLOBE_Y;
  g.add(globe);

  /* ── filament + support posts ────────────────────────────── */
  const filamentMat = new THREE.MeshStandardMaterial({
    color: 0xffe9a8, emissive: 0xfef08a, emissiveIntensity: lit ? 4.0 : 0.08,
    metalness: 0.9, roughness: 0.3, toneMapped: false,
  });

  // coiled helix
  const helixPts = [];
  const TURNS_F = 6, R_F = 0.065, Y_F0 = 1.28, Y_F1 = 1.70;
  for (let i = 0; i <= TURNS_F * 24; i++) {
    const t = i / (TURNS_F * 24);
    const a = t * TURNS_F * Math.PI * 2;
    helixPts.push(new THREE.Vector3(
      Math.cos(a) * R_F, Y_F0 + t * (Y_F1 - Y_F0), Math.sin(a) * R_F));
  }
  const filament = new THREE.Mesh(
    new THREE.TubeGeometry(new THREE.CatmullRomCurve3(helixPts), 220, 0.012, 8, false),
    filamentMat);
  filament.position.y = GLOBE_Y;
  g.add(filament);

  // two nickel posts from the neck up to the filament
  for (const x of [-R_F, R_F]) {
    const post = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.56, 8), matNickel);
    post.position.set(x, GLOBE_Y + 1.02, 0);
    g.add(post);
  }

  /* ── light source + inner glow ───────────────────────────── */
  const light = new THREE.PointLight(0xfef08a, lit ? 4.0 : 0.0, 9, 2);
  light.position.set(0, GLOBE_Y + 1.49, 0);
  g.add(light);

  const glow = new THREE.Mesh(
    new THREE.SphereGeometry(0.16, 16, 12),
    new THREE.MeshBasicMaterial({
      color: 0xfef08a, transparent: true, opacity: lit ? 0.45 : 0.0,
      blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
    }));
  glow.position.copy(light.position);
  g.add(glow);

  /* ── API ─────────────────────────────────────────────────── */
  g.userData.setLit = (v) => {
    filamentMat.emissiveIntensity = v ? 4.0 : 0.08;
    light.intensity = v ? 4.0 : 0.0;
    glow.material.opacity = v ? 0.45 : 0.0;
  };
  g.userData.light = light;
  g.userData.filamentMat = filamentMat;
  g.userData.glassMat = glassMat;
  return g;
}


/* ══════════════════════════════════════════════════════════════════
   3) MABUCHI 130 HOBBY DC MOTOR
   Can 1.5 (X) × 1.1 (Y) × 2.0 (Z). Shaft spins around +Z.
   userData.update(dt, rpm) spins the rotor.
   ══════════════════════════════════════════════════════════════════ */
export function createMabuchi130({ rpm = 0 } = {}) {
  const g = new THREE.Group();
  g.name = 'Mabuchi_130_Motor';

  const matSteel  = new THREE.MeshStandardMaterial({ color: 0xd4d4d8, metalness: 0.92, roughness: 0.30 });
  const matBrass  = metal(0xb08d57, 0.30);
  const matCopper = metal(0xb87333, 0.35);
  const matPlastic = new THREE.MeshStandardMaterial({ color: 0xe4e4e7, roughness: 0.85, metalness: 0.0 });
  const matDark   = new THREE.MeshStandardMaterial({ color: 0x0a0a0a, roughness: 0.9, metalness: 0.2 });
  const matShaft  = metal(0xe8e8ec, 0.12);

  /* ── flat-sided oval can ─────────────────────────────────── */
  const can = new THREE.Mesh(new RoundedBoxGeometry(1.5, 1.1, 2.0, 4, 0.26), matSteel);
  g.add(can);

  /* ── front bearing boss ──────────────────────────────────── */
  const boss = new THREE.Mesh(new THREE.CylinderGeometry(0.30, 0.35, 0.25, 32), matBrass);
  boss.rotation.x = Math.PI / 2;
  boss.position.z = 1.125;                     // 1.00 → 1.25
  g.add(boss);

  /* ── front vent holes ────────────────────────────────────── */
  for (let i = 0; i < 4; i++) {
    const a = Math.PI / 4 + i * Math.PI / 2;
    const hole = new THREE.Mesh(new THREE.CylinderGeometry(0.055, 0.055, 0.09, 12), matDark);
    hole.rotation.x = Math.PI / 2;
    hole.position.set(Math.cos(a) * 0.55, Math.sin(a) * 0.42, 0.985);
    g.add(hole);
  }

  /* ── side notches ────────────────────────────────────────── */
  for (const s of [-1, 1]) {
    const notch = new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.22, 0.42), matDark);
    notch.position.set(s * 0.755, 0.0, 0.66);
    g.add(notch);
  }

  /* ── rotor (shaft) ───────────────────────────────────────── */
  const rotor = new THREE.Group();
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.08, 1.2, 20), matShaft);
  shaft.rotation.x = Math.PI / 2;
  shaft.position.z = 0.6;
  rotor.add(shaft);
  const shaftTip = new THREE.Mesh(new THREE.SphereGeometry(0.08, 16, 12), matShaft);
  shaftTip.position.z = 1.2;
  rotor.add(shaftTip);
  rotor.position.z = 1.15;
  g.add(rotor);

  /* ── rear plastic end-bell ───────────────────────────────── */
  const bell = new THREE.Mesh(new RoundedBoxGeometry(1.44, 1.04, 0.22, 3, 0.18), matPlastic);
  bell.position.z = -1.09;
  g.add(bell);

  const block = new THREE.Mesh(new THREE.BoxGeometry(0.92, 0.30, 0.12), matPlastic);
  block.position.set(0, 0.18, -1.19);
  g.add(block);

  /* ── copper solder terminals ─────────────────────────────── */
  for (const x of [-0.38, 0.38]) {
    const tab = new THREE.Mesh(new THREE.BoxGeometry(0.20, 0.055, 0.42), matCopper);
    tab.position.set(x, 0.18, -1.38);
    g.add(tab);
    const bend = new THREE.Mesh(new THREE.BoxGeometry(0.20, 0.16, 0.055), matCopper);
    bend.position.set(x, 0.10, -1.58);
    g.add(bend);
  }

  /* ── API ─────────────────────────────────────────────────── */
  let speed = rpm;
  g.userData.setRPM = (v) => { speed = v; };
  g.userData.update = (dt) => { rotor.rotation.z += (speed / 60) * Math.PI * 2 * dt; };
  g.userData.rotor = rotor;
  return g;
}


/* ══════════════════════════════════════════════════════════════════
   4) ALLIGATOR CLIP TEST LEADS
   createTestLead({start, end, color, sag})
   Clip local frame: origin = wire entry, mouth along +Z.
   ══════════════════════════════════════════════════════════════════ */

/** Jaw profile (u = distance from pivot, v = height). */
const JAW_PROFILE = [
  [0.00, -0.045], [0.00, 0.095], [0.10, 0.120], [0.26, 0.120],
  [0.46, 0.098], [0.66, 0.062], [0.82, 0.030], [0.88, 0.008],
  [0.88, -0.012], [0.80, -0.028], [0.60, -0.012], [0.40, -0.004],
  [0.20, 0.000], [0.08, -0.020],
];

const JAW_THICKNESS = 0.20;

function buildJawGeometry() {
  const shape = new THREE.Shape();
  JAW_PROFILE.forEach(([u, v], i) => (i ? shape.lineTo(u, v) : shape.moveTo(u, v)));
  shape.closePath();
  const geo = new THREE.ExtrudeGeometry(shape, {
    depth: JAW_THICKNESS, bevelEnabled: true,
    bevelThickness: 0.012, bevelSize: 0.012, bevelSegments: 1, curveSegments: 2,
  });
  // shape (u,v) → world (z,y), extrusion → world x
  geo.rotateY(-Math.PI / 2);
  geo.translate(JAW_THICKNESS / 2, 0, 0);
  geo.computeVertexNormals();
  return geo;
}

export function createAlligatorClip({ color = 0xef4444, open = 0.12 } = {}) {
  const g = new THREE.Group();
  g.name = 'AlligatorClip';

  const matJaw = new THREE.MeshStandardMaterial({
    color: 0xd2d2d8, metalness: 0.95, roughness: 0.34, side: THREE.DoubleSide,
  });
  const matBoot = rubber(color, 0.60);
  const matBootRib = rubber(new THREE.Color(color).multiplyScalar(0.72).getHex(), 0.68);
  const matChrome = metal(0xf0f0f4, 0.08);

  /* ── flexible boot ───────────────────────────────────────── */
  const bootProf = [
    [0.078, 0.00], [0.088, 0.06], [0.098, 0.16], [0.108, 0.28],
    [0.118, 0.40], [0.126, 0.47], [0.118, 0.53], [0.100, 0.56],
  ];
  const boot = new THREE.Mesh(lathe(bootProf, 28), matBoot);
  boot.rotation.x = Math.PI / 2;               // +Y → +Z
  g.add(boot);

  for (const z of [0.14, 0.26, 0.38]) {
    const rib = new THREE.Mesh(new THREE.TorusGeometry(0.105, 0.011, 8, 24), matBootRib);
    rib.position.z = z;
    g.add(rib);
  }

  /* ── jaws (pivot at z = 0.62) ────────────────────────────── */
  const PIVOT_Z = 0.62;
  const jawGeo = buildJawGeometry();

  const makeJaw = (mirror) => {
    const grp = new THREE.Group();
    grp.position.z = PIVOT_Z;
    grp.scale.y = mirror ? -1 : 1;
    grp.rotation.x = mirror ? open : -open;

    grp.add(new THREE.Mesh(jawGeo, matJaw));

    // interlocking serrated teeth (offset half pitch between jaws)
    const u0 = mirror ? 0.505 : 0.46;
    for (let i = 0; i < 5; i++) {
      const u = u0 + i * 0.09;
      const tooth = new THREE.Mesh(new THREE.ConeGeometry(0.024, 0.052, 4), matJaw);
      tooth.rotation.x = Math.PI;               // point −Y
      tooth.rotation.y = Math.PI / 4;
      tooth.position.set(0, -0.004, u);
      grp.add(tooth);
    }
    return grp;
  };

  g.add(makeJaw(false), makeJaw(true));

  /* ── pivot rivet ─────────────────────────────────────────── */
  const rivet = new THREE.Mesh(new THREE.CylinderGeometry(0.052, 0.052, JAW_THICKNESS + 0.07, 16), matChrome);
  rivet.rotation.z = Math.PI / 2;
  rivet.position.set(0, 0.02, PIVOT_Z);
  g.add(rivet);
  for (const s of [-1, 1]) {
    const head = new THREE.Mesh(new THREE.CylinderGeometry(0.072, 0.072, 0.03, 16), matChrome);
    head.rotation.z = Math.PI / 2;
    head.position.set(s * (JAW_THICKNESS / 2 + 0.045), 0.02, PIVOT_Z);
    g.add(head);
  }

  /* ── torsion spring ──────────────────────────────────────── */
  const coil = new THREE.Mesh(new THREE.TorusGeometry(0.082, 0.014, 8, 20), matChrome);
  coil.rotation.y = Math.PI / 2;
  coil.position.set(0, 0.02, PIVOT_Z);
  g.add(coil);
  for (const s of [-1, 1]) {
    const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.013, 0.013, 0.30, 8), matChrome);
    leg.position.set(0, 0.02 + s * 0.14, PIVOT_Z + 0.10);
    leg.rotation.x = s * 0.55;
    g.add(leg);
  }

  return g;
}

export function createTestLead({
  start = new THREE.Vector3(-3, 0, 0),
  end = new THREE.Vector3(3, 0, 0),
  color = 0xef4444,
  sag = 1.1,
  wireRadius = 0.06,
} = {}) {
  const g = new THREE.Group();
  g.name = 'TestLead';

  /* ── sagging wire (Catmull-Rom tube) ─────────────────────── */
  const ctrl = [];
  const SEG = 6;
  for (let i = 0; i <= SEG; i++) {
    const t = i / SEG;
    const p = start.clone().lerp(end, t);
    p.y -= Math.sin(t * Math.PI) * sag;
    ctrl.push(p);
  }
  const curve = new THREE.CatmullRomCurve3(ctrl, false, 'catmullrom', 0.5);
  const wire = new THREE.Mesh(
    new THREE.TubeGeometry(curve, 140, wireRadius, 12, false),
    rubber(color, 0.58));
  g.add(wire);

  /* ── clips at both ends ──────────────────────────────────── */
  const clipStart = createAlligatorClip({ color });
  clipStart.position.copy(start);
  clipStart.quaternion.setFromUnitVectors(
    new THREE.Vector3(0, 0, 1),
    curve.getTangentAt(0).negate());        // mouth points away from the wire
  g.add(clipStart);

  const clipEnd = createAlligatorClip({ color });
  clipEnd.position.copy(end);
  clipEnd.quaternion.setFromUnitVectors(
    new THREE.Vector3(0, 0, 1),
    curve.getTangentAt(1));
  g.add(clipEnd);

  g.userData.curve = curve;
  return g;
}


/* ══════════════════════════════════════════════════════════════════
   5) INDUSTRIAL HEAVY-DUTY TOGGLE SWITCH
   Base 2.8 × 1.4 × 1.2 (bottom at y = 0). Lever ±28° about Z.
   userData.setToggle(on) · userData.update(dt)
   ══════════════════════════════════════════════════════════════════ */
export function createToggleSwitch({ on = false } = {}) {
  const g = new THREE.Group();
  g.name = 'HeavyDutyToggleSwitch';

  const matBody  = new THREE.MeshStandardMaterial({ color: 0x1e293b, roughness: 0.78, metalness: 0.05 });
  const matPlate = metal(0xc9ccd4, 0.35);
  const matChrome = metal(0xf2f2f6, 0.07);
  const matRed   = new THREE.MeshStandardMaterial({ color: 0xdc2626, roughness: 0.45, metalness: 0.05 });
  const matDark  = new THREE.MeshStandardMaterial({ color: 0x0b1220, roughness: 0.65, metalness: 0.05 });

  /* ── base enclosure ──────────────────────────────────────── */
  const base = new THREE.Mesh(new RoundedBoxGeometry(2.8, 1.2, 1.4, 3, 0.10), matBody);
  base.position.y = 0.60;
  g.add(base);

  /* ── mounting plate (beveled) ────────────────────────────── */
  const plate = new THREE.Mesh(new RoundedBoxGeometry(2.9, 0.16, 1.5, 2, 0.06), matPlate);
  plate.position.y = 1.28;                     // top face at y = 1.36
  g.add(plate);

  /* ── "OFF" matte panel (left) ────────────────────────────── */
  const offTex = textTexture('OFF', {
    w: 512, h: 512, bg: '#0b1220', color: '#cbd5e1',
    font: 'bold 190px "Arial Black", Arial, sans-serif',
  });
  const offPanel = topDecal(offTex, 0.90, 0.90);
  offPanel.position.set(-0.78, 1.365, 0);
  g.add(offPanel);

  /* ── "ON" red plate (right, slightly raised) ─────────────── */
  const redPlate = new THREE.Mesh(new RoundedBoxGeometry(0.95, 0.06, 0.95, 2, 0.03), matRed);
