  const onTex = textTexture('ON', {
    w: 512, h: 512, bg: '#dc2626', color: '#ffffff',
    font: 'bold 240px "Arial Black", Arial, sans-serif',
  });
  const onPanel = topDecal(onTex, 0.90, 0.90);
  onPanel.position.set(0.78, 1.425, 0);
  g.add(onPanel);

  /* ── mounting screw holes ────────────────────────────────── */
  for (const sx of [-1.32, 1.32]) {
    for (const sz of [-0.58, 0.58]) {
      const ring = new THREE.Mesh(new THREE.TorusGeometry(0.075, 0.018, 8, 20), matDark);
      ring.rotation.x = Math.PI / 2;
      ring.position.set(sx, 1.362, sz);
      g.add(ring);
      const screw = new THREE.Mesh(new THREE.CylinderGeometry(0.065, 0.065, 0.04, 16), matChrome);
      screw.position.set(sx, 1.375, sz);
      g.add(screw);
      const slot = new THREE.Mesh(new THREE.BoxGeometry(0.10, 0.012, 0.022), matDark);
      slot.position.set(sx, 1.398, sz);
      g.add(slot);
    }
  }

  /* ── central threaded collar + hex nut + LED ring ────────── */
  const collarProf = [];
  const CY0 = 1.36, CH = 0.40;
  for (let i = 0; i <= 96; i++) {
    const t = i / 96;
    collarProf.push([0.28 + 0.024 * Math.sin(t * Math.PI * 2 * 6), CY0 + t * CH]);
  }
  collarProf.push([0.30, CY0 + CH + 0.02]);
  const collar = new THREE.Mesh(
    new THREE.LatheGeometry(collarProf.map(([r, y]) => new THREE.Vector2(r, y)), 40),
    matChrome);
  g.add(collar);

  const hexNut = new THREE.Mesh(new THREE.CylinderGeometry(0.42, 0.42, 0.14, 6), matChrome);
  hexNut.position.y = 1.43;
  g.add(hexNut);

  const matLED = new THREE.MeshStandardMaterial({
    color: 0x38bdf8, emissive: 0x38bdf8, emissiveIntensity: on ? 3.0 : 0.05,
    roughness: 0.3, metalness: 0.0, toneMapped: false,
  });
  const ledRing = new THREE.Mesh(new THREE.TorusGeometry(0.295, 0.028, 10, 40), matLED);
  ledRing.rotation.x = Math.PI / 2;
  ledRing.position.y = 1.775;
  g.add(ledRing);

  /* ── bat lever (pivot at y = 1.78) ───────────────────────── */
  const leverPivot = new THREE.Group();
  leverPivot.position.set(0, 1.78, 0);
  g.add(leverPivot);

  const boot = new THREE.Mesh(new THREE.CylinderGeometry(0.20, 0.24, 0.10, 24), matDark);
  boot.position.y = 0.02;
  leverPivot.add(boot);

  const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.065, 0.150, 1.05, 24), matChrome);
  stem.position.y = 0.10 + 0.525;
  leverPivot.add(stem);

  const knob = new THREE.Mesh(new THREE.SphereGeometry(0.135, 24, 18), matChrome);
  knob.position.y = 1.21;
  leverPivot.add(knob);

  /* ── animation / API ─────────────────────────────────────── */
  const state = { on: !!on };
  const targetAngle = () => (state.on ? -D2R(28) : D2R(28));
  leverPivot.rotation.z = targetAngle();

  g.userData.setToggle = (v) => {
    state.on = !!v;
    matLED.emissiveIntensity = state.on ? 3.0 : 0.05;
  };
  g.userData.isOn = () => state.on;
  g.userData.update = (dt) => {
    leverPivot.rotation.z = THREE.MathUtils.damp(
      leverPivot.rotation.z, targetAngle(), 14, Math.min(dt, 0.05));
  };
  g.userData.lever = leverPivot;
  return g;
}


