/** Helical coil between two points (for test leads). */
function coiledLead(a, b, color, { turns = 10, coilRadius = 0.16, tube = 0.032 } = {}) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const axis = dir.clone().normalize();
  const ref = Math.abs(axis.y) > 0.9 ? new THREE.Vector3(1, 0, 0) : new THREE.Vector3(0, 1, 0);
  const n1 = new THREE.Vector3().crossVectors(axis, ref).normalize();
  const n2 = new THREE.Vector3().crossVectors(axis, n1).normalize();

  const pts = [];
  const N = turns * 12;
  for (let i = 0; i <= N; i++) {
    const t = i / N;
    const ang = t * turns * Math.PI * 2;
    pts.push(a.clone().addScaledVector(dir, t)
      .addScaledVector(n1, Math.cos(ang) * coilRadius)
      .addScaledVector(n2, Math.sin(ang) * coilRadius));
  }
  const curve = new THREE.CatmullRomCurve3(pts, false, 'catmullrom', 0.25);
  return new THREE.Mesh(new THREE.TubeGeometry(curve, N, tube, 8, false), rubber(color, 0.55));
}

/** Banana-plug test probe. Origin = butt of the handle, needle along +Y. */
export function createTestProbe({ color = 0xef4444 } = {}) {
  const g = new THREE.Group();
  g.name = 'TestProbe';
  const matBody = rubber(color, 0.55);
  const matChrome = metal(0xe8e8ec, 0.12);

  const plug = new THREE.Mesh(new THREE.CylinderGeometry(0.055, 0.055, 0.18, 16), matChrome);
  plug.position.y = 0.09;
  g.add(plug);

  const grip = new THREE.Mesh(new THREE.CylinderGeometry(0.085, 0.115, 0.95, 20), matBody);
  grip.position.y = 0.18 + 0.475;
  g.add(grip);

  for (let i = 0; i < 5; i++) {
    const rib = new THREE.Mesh(new THREE.TorusGeometry(0.098, 0.010, 8, 20),
      rubber(new THREE.Color(color).multiplyScalar(0.75).getHex(), 0.7));
    rib.rotation.x = Math.PI / 2;
    rib.position.y = 0.36 + i * 0.16;
    g.add(rib);
  }

  const collar = new THREE.Mesh(new THREE.CylinderGeometry(0.075, 0.075, 0.10, 16), matChrome);
  collar.position.y = 1.18;
  g.add(collar);

  const needle = new THREE.Mesh(new THREE.ConeGeometry(0.028, 0.36, 14), matChrome);
  needle.position.y = 1.41;
  g.add(needle);

  return g;
}

export function createMultimeter({ reading = '1.50' } = {}) {
  const g = new THREE.Group();
  g.name = 'DigitalMultimeter';

  const W = 2.2, H = 3.6, D = 0.9, FRONT = D / 2;   // 0.45
  const matYellow = new THREE.MeshStandardMaterial({ color: 0xfacc15, roughness: 0.74, metalness: 0.02 });
  const matYellowDark = new THREE.MeshStandardMaterial({ color: 0xe0b100, roughness: 0.78, metalness: 0.02 });
  const matBlack = new THREE.MeshStandardMaterial({ color: 0x18181b, roughness: 0.55, metalness: 0.1 });
  const matBezel = new THREE.MeshStandardMaterial({ color: 0x111827, roughness: 0.42, metalness: 0.15 });
  const matChrome = metal(0xd6d6dc, 0.20);

  /* ── ergonomic holster (vertex-tapered rounded box) ──────── */
  const holsterGeo = new RoundedBoxGeometry(W, H, D, 6, 0.26);
  {
    const pos = holsterGeo.attributes.position;
    for (let i = 0; i < pos.count; i++) {
      const y = pos.getY(i);
      const t = y / (H / 2);
      pos.setX(i, pos.getX(i) * (1 + 0.045 * t));
      pos.setZ(i, pos.getZ(i) * (1 - 0.03 * t));
    }
    holsterGeo.computeVertexNormals();
  }
  const holster = new THREE.Mesh(holsterGeo, matYellow);
  g.add(holster);

  /* ── side grip grooves ───────────────────────────────────── */
  for (const s of [-1, 1]) {
    for (let i = 0; i < 5; i++) {
      const groove = new THREE.Mesh(new RoundedBoxGeometry(0.05, 0.07, 0.56, 2, 0.025), matYellowDark);
      groove.position.set(s * 1.08, -1.05 + i * 0.20, 0);
      g.add(groove);
    }
  }

  /* ── LCD display ─────────────────────────────────────────── */
  const bezel = new THREE.Mesh(new RoundedBoxGeometry(1.72, 1.02, 0.12, 2, 0.06), matBezel);
  bezel.position.set(0, 1.10, FRONT - 0.01);
  g.add(bezel);

  const lcdTex = canvasTexture(1024, 512, (ctx, w, h) => {
    ctx.fillStyle = '#c3cfba';
    ctx.fillRect(0, 0, w, h);
    // faint segment ghosting
    ctx.fillStyle = 'rgba(30,45,30,0.08)';
    ctx.font = 'bold 300px "Courier New", monospace';
    ctx.textAlign = 'right'; ctx.textBaseline = 'middle';
    ctx.fillText('88.8', w - 250, h / 2 + 20);
    // reading
    ctx.fillStyle = '#16241a';
    ctx.font = 'bold 300px "Courier New", monospace';
    ctx.fillText(reading, w - 260, h / 2 + 20);
    ctx.font = 'bold 120px "Courier New", monospace';
    ctx.fillText('V', w - 110, h / 2 + 60);
    // indicator strip
    ctx.font = 'bold 46px Arial';
    ctx.fillStyle = '#2f4030';
    ctx.textAlign = 'left';
    ctx.fillText('DC', 50, 70);
    ctx.fillText('AUTO', 50, h - 55);
  });
  const lcd = new THREE.Mesh(
    new THREE.PlaneGeometry(1.54, 0.84),
    new THREE.MeshStandardMaterial({
      map: lcdTex, emissive: 0xffffff, emissiveMap: lcdTex,
      emissiveIntensity: 0.28, roughness: 0.22, metalness: 0.0,
    }),
  );
  lcd.position.set(0, 1.10, FRONT + 0.055);
  g.add(lcd);

  /* ── rotary selector dial ────────────────────────────────── */
  const DIAL = new THREE.Vector3(0, -0.45, FRONT);
  const dial = new THREE.Mesh(new THREE.CylinderGeometry(0.60, 0.62, 0.22, 40), matBlack);
  dial.rotation.x = Math.PI / 2;
  dial.position.copy(DIAL).setZ(FRONT + 0.04);
  g.add(dial);

  // knurled rim
  for (let i = 0; i < 32; i++) {
    const a = (i / 32) * Math.PI * 2;
    const knurl = new THREE.Mesh(new THREE.BoxGeometry(0.035, 0.035, 0.20), matBlack);
    knurl.position.set(
      Math.cos(a) * 0.605, Math.sin(a) * 0.605 + DIAL.y, FRONT + 0.04);
    knurl.rotation.z = a;
    g.add(knurl);
  }

  // pointer notch
  const pointer = new THREE.Mesh(new THREE.ConeGeometry(0.055, 0.20, 3), matChrome);
  pointer.position.set(0, DIAL.y + 0.42, FRONT + 0.17);
  g.add(pointer);

  // range markings
  const ranges = [
    { text: 'OFF', a: 220 }, { text: 'V=', a: 175 }, { text: 'V~', a: 130 },
    { text: 'mA', a: 85 }, { text: 'Ω', a: 40 },
  ];
  for (const r of ranges) {
    const tex = textTexture(r.text, { w: 256, h: 160, color: '#f8fafc', font: 'bold 96px Arial' });
    const lbl = new THREE.Mesh(
      new THREE.PlaneGeometry(0.30, 0.19),
      new THREE.MeshBasicMaterial({ map: tex, transparent: true, toneMapped: false }),
    );
    const rad = D2R(r.a);
    lbl.position.set(
      Math.cos(rad) * 0.86,
      DIAL.y + Math.sin(rad) * 0.86,
      FRONT + 0.012);
    g.add(lbl);
  }

  /* ── 4 input jacks ───────────────────────────────────────── */
  const JACK_Y = -1.52;
  const jacks = [
    { x: -0.70, label: '10A', color: 0xef4444 },
    { x: -0.24, label: 'mA', color: 0x18181b },
    { x: 0.24, label: 'COM', color: 0x18181b },
    { x: 0.70, label: 'VΩ', color: 0xef4444 },
  ];
  for (const j of jacks) {
    const ring = new THREE.Mesh(new THREE.CylinderGeometry(0.175, 0.175, 0.07, 24), matBlack);
    ring.rotation.x = Math.PI / 2;
    ring.position.set(j.x, JACK_Y, FRONT + 0.01);
    g.add(ring);

    const bore = new THREE.Mesh(new THREE.CylinderGeometry(0.105, 0.105, 0.10, 20),
      new THREE.MeshStandardMaterial({ color: 0x000000, roughness: 1.0 }));
    bore.rotation.x = Math.PI / 2;
    bore.position.set(j.x, JACK_Y, FRONT - 0.01);
    g.add(bore);

    const accent = new THREE.Mesh(new THREE.TorusGeometry(0.135, 0.018, 8, 24),
      new THREE.MeshStandardMaterial({ color: j.color, roughness: 0.45 }));
    accent.position.set(j.x, JACK_Y, FRONT + 0.05);
    g.add(accent);

    const tex = textTexture(j.label, { w: 256, h: 128, color: '#f8fafc', font: 'bold 84px Arial' });
    const lbl = new THREE.Mesh(new THREE.PlaneGeometry(0.28, 0.14),
      new THREE.MeshBasicMaterial({ map: tex, transparent: true, toneMapped: false }));
    lbl.position.set(j.x, JACK_Y + 0.27, FRONT + 0.008);
    g.add(lbl);
  }

  /* ── probes + coiled leads ───────────────────────────────── */
  const jackRed = new THREE.Vector3(0.70, JACK_Y, FRONT + 0.06);
  const jackBlack = new THREE.Vector3(0.24, JACK_Y, FRONT + 0.06);

  const redProbe = createTestProbe({ color: 0xef4444 });
  redProbe.position.set(1.55, -1.62, 1.30);
  redProbe.rotation.set(-0.42, -0.25, 0.06);
  g.add(redProbe);
  g.add(coiledLead(jackRed, redProbe.position.clone().setY(-1.60), 0xef4444,
    { turns: 9, coilRadius: 0.15 }));

  const blackProbe = createTestProbe({ color: 0x18181b });
  blackProbe.position.set(0.55, -1.62, 1.55);
  blackProbe.rotation.set(-0.42, 0.18, -0.05);
  g.add(blackProbe);
  g.add(coiledLead(jackBlack, blackProbe.position.clone().setY(-1.60), 0x18181b,
    { turns: 8, coilRadius: 0.15 }));

  /* ── API ─────────────────────────────────────────────────── */
  g.userData.setReading = (txt) => {
    const t = canvasTexture(1024, 512, (ctx, w, h) => {
      ctx.fillStyle = '#c3cfba'; ctx.fillRect(0, 0, w, h);
      ctx.fillStyle = '#16241a';
      ctx.font = 'bold 300px "Courier New", monospace';
      ctx.textAlign = 'right'; ctx.textBaseline = 'middle';
      ctx.fillText(txt, w - 260, h / 2 + 20);
      ctx.font = 'bold 120px "Courier New", monospace';
      ctx.fillText('V', w - 110, h / 2 + 60);
    });
    lcd.material.map.dispose();
    lcd.material.emissiveMap.dispose();
    lcd.material.map = t;
    lcd.material.emissiveMap = t;
    lcd.material.needsUpdate = true;
  };
  g.userData.lcd = lcd;
  g.userData.dial = dial;
  return g;
}


